<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($title) ?> - BloodLink</title><link rel="stylesheet" href="public/assets/css/style.css"></head><body>
<header class="topbar"><a class="brand" href="index.php">BloodLink <small>Services de santé</small></a><a class="btn secondary" href="javascript:history.back()">Retour</a></header><main class="container narrow"><p class="eyebrow">FORMULAIRE</p><h1><?= htmlspecialchars($title) ?></h1>
<?php if($errors): ?><div class="error"><ul><?php foreach($errors as $err): ?><li><?= htmlspecialchars($err) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="form-card js-validate" method="post" novalidate><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><div class="grid">
<?php foreach($formFields as $key=>$label): ?><label class="<?= in_array($key,['description','commentaire','instructions','notes','symptomes','reponse'],true)?'wide':'' ?>"><?= htmlspecialchars($label) ?>
<?php if($key==='etablissement'): ?><select name="etablissement" required><option value="">Choisir un établissement</option><?php foreach($establishments as $e): ?><option value="<?= htmlspecialchars($e['nom']) ?>" <?= (($data[$key]??'')===$e['nom'])?'selected':'' ?>><?= htmlspecialchars($e['nom']) ?></option><?php endforeach; ?></select>
<?php elseif(in_array($key,['description','commentaire','instructions','notes','symptomes','reponse'],true)): ?><textarea name="<?= $key ?>" rows="3" <?= in_array($key,$def['required'],true)?'required':'' ?>><?= htmlspecialchars($data[$key]??'') ?></textarea>
<?php elseif($key==='date'||$key==='dateDebut'||$key==='dateFin'): ?><input type="date" name="<?= $key ?>" value="<?= htmlspecialchars($data[$key]??'') ?>" <?= in_array($key,$def['required'],true)?'required':'' ?>>
<?php elseif($key==='heureCoucher'||$key==='heureReveil'): ?><input type="time" name="<?= $key ?>" value="<?= htmlspecialchars($data[$key]??'') ?>" required>
<?php elseif($key==='note'||$key==='quantite'||$key==='duree'||$key==='distance'||$key==='progression'): ?><input type="number" name="<?= $key ?>" min="<?= $key==='note'?1:0 ?>" <?= $key==='note'?'max="5"':'' ?> step="any" value="<?= htmlspecialchars($data[$key]??'') ?>" <?= in_array($key,$def['required'],true)?'required':'' ?>>
<?php elseif($key==='statut'): ?><select name="statut"><option>Actif</option><option>Disponible</option><option>Indisponible</option><option>En maintenance</option><option>En attente</option><option>En cours</option><option>Résolu</option><option>Rejeté</option></select>
<?php else: ?><input name="<?= $key ?>" value="<?= htmlspecialchars($data[$key]??'') ?>" <?= in_array($key,$def['required'],true)?'required':'' ?>><?php endif; ?></label><?php endforeach; ?></div>
<p class="hint">Les champs marqués obligatoires sont contrôlés en JavaScript et revérifiés en PHP. Les données sont temporaires dans la session de démonstration.</p><div class="actions"><button class="btn" type="submit">Enregistrer</button><a class="btn secondary" href="javascript:history.back()">Annuler</a></div></form></main><script src="public/assets/js/app.js"></script></body></html>
